package com.nigson.acceptance.carrier;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import com.nigson.acceptance.fulfillment.ShipmentFixture;
import com.nigson.commerce.fulfillment.*;
import com.nigson.commerce.inventory.InventoryAuthority;
import com.nigson.commerce.platform.AuditWriter;
import com.nigson.shared.security.ActorAssertion;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import static org.assertj.core.api.Assertions.*;
class CarrierReconciliationPersistenceTest {
 ShipmentFixture f;JdbcTemplate jdbc;CarrierReconciliationCommands commands;FulfillmentValues.Shipment shipment;long seconds;Clock clock;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"native isolated owned PostgreSQL required");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);f=new ShipmentFixture(jdbc,manager);CarrierContextPersistenceTest.freeze(f);shipment=f.create("5","FEDEX",null,"reconciliation-intent");ngMarket(f);clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId ignored){return this;}public Instant instant(){return Instant.now().plusSeconds(seconds);}};commands=new CarrierReconciliationCommands(jdbc,manager,new InventoryAuthority(jdbc),new AuditWriter(jdbc,clock,f.metrics),clock);}
 static void ngMarket(ShipmentFixture f){UUID market=f.inventory.jdbc.queryForObject("SELECT id FROM commerce.market WHERE code='NG' AND currency_code='NGN'",UUID.class);f.inventory.jdbc.update("UPDATE commerce.sales_order SET market_id=? WHERE id=?",market,f.order);}
 @AfterEach void cleanup(){if(f!=null)f.close();}
 CarrierReconciliationCommands.Intent claim(String key){return commands.claim(f.inventory.actor,shipment.id(),0,"Synthetic operator reference reconciliation",key,UUID.randomUUID());}
 CarrierReconciliationValues.Result accepted(){return new CarrierReconciliationValues.Result(shipment.id(),"UNKNOWN",UUID.randomUUID());}
 @Test void sourceBindsOriginalFrozenBookingAndReplaysUnknownAcrossShipmentVersionChange(){var first=claim("unknown");assertThat(first.request().bookingRequestId()).isEqualTo(jdbc.queryForObject("SELECT booking_request_id FROM commerce.shipment WHERE id=?",UUID.class,shipment.id()));assertThat(first.request().mode()).isEqualTo("MOCK");commands.unknown(first,f.inventory.actor,shipment.id(),UUID.randomUUID());jdbc.update("UPDATE commerce.shipment SET package_snapshot=jsonb_set(package_snapshot,'{bookingReference}',?::jsonb) WHERE id=?","\""+UUID.randomUUID()+"\"",shipment.id());assertThatThrownBy(()->claim("unknown")).hasMessage("FULFILLMENT_RULE_VIOLATION");jdbc.update("UPDATE commerce.shipment SET package_snapshot=jsonb_set(package_snapshot,'{bookingReference}',?::jsonb) WHERE id=?","\""+first.request().bookingRequestId()+"\"",shipment.id());jdbc.update("UPDATE commerce.shipment SET version=version+1,status='EXCEPTION' WHERE id=?",shipment.id());var replay=claim("unknown");assertThat(replay.command()).isEqualTo(first.command());assertThat(replay.request()).isEqualTo(first.request());var accepted=accepted();commands.finish(replay,f.inventory.actor,shipment.id(),UUID.randomUUID(),accepted,null);assertThat(claim("unknown").completed()).isEqualTo(accepted);assertThat(f.value("allocated")).isEqualByComparingTo("5");assertThat(f.value("on_hand")).isEqualByComparingTo("10");}
 @Test void freshCommandRequiresVersionAndUnchangedSourceModeReference(){assertThatThrownBy(()->commands.claim(f.inventory.actor,shipment.id(),2,"Synthetic stale version request","version",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");jdbc.update("UPDATE commerce.sales_order SET market_id=? WHERE id=?",f.inventory.orders.market,f.order);assertThatThrownBy(()->claim("foreign-market")).hasMessage("FULFILLMENT_RULE_VIOLATION");ngMarket(f);jdbc.update("UPDATE commerce.shipment SET package_snapshot=jsonb_set(package_snapshot,'{mode}','\"LIVE\"') WHERE id=?",shipment.id());assertThatThrownBy(()->claim("mode")).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.idempotency_record WHERE operation='API-191-PRIVATE-ACK' AND resource_id=?",Integer.class,shipment.id())).isZero();}
 @Test void activeLeaseAndChangedBodyKeysCannotIssueAnotherCommand(){var first=claim("same");assertThatThrownBy(()->claim("same")).hasMessage("IDEMPOTENCY_IN_PROGRESS");assertThatThrownBy(()->commands.claim(f.inventory.actor,shipment.id(),0,"Synthetic different operator reason","same",UUID.randomUUID())).hasMessage("IDEMPOTENCY_HASH_MISMATCH");seconds=31;var reclaimed=claim("same");assertThat(reclaimed.command()).isEqualTo(first.command());assertThat(reclaimed.generation()).isGreaterThan(first.generation());assertThatThrownBy(()->commands.finish(first,f.inventory.actor,shipment.id(),UUID.randomUUID(),accepted(),null)).hasMessage("IDEMPOTENCY_IN_PROGRESS");}
 @Test void currentRoleOrganizationAndRecentMfaAreRequiredBeforeReplay(){var first=claim("authority");commands.finish(first,f.inventory.actor,shipment.id(),UUID.randomUUID(),accepted(),null);var actor=f.inventory.actor;var stale=new ActorAssertion.Actor(actor.party(),actor.identityIssuer(),actor.identitySubject(),null,actor.roles(),actor.scopes(),Instant.now().minusSeconds(901));assertThatThrownBy(()->commands.authority(stale)).hasMessage("ACTOR_TRUST_REJECTED");var selected=new ActorAssertion.Actor(actor.party(),actor.identityIssuer(),actor.identitySubject(),UUID.randomUUID(),actor.roles(),actor.scopes(),Instant.now());assertThatThrownBy(()->commands.authority(selected)).hasMessage("ACCESS_DENIED");jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=?",actor.party());assertThatThrownBy(()->claim("authority")).hasMessage("ACCESS_DENIED");}
 @Test void auditFailureRollsBackIntentAndPreservesAcceptedRemoteAckRecovery(){f.inventory.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->claim("audit")).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{f.inventory.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.idempotency_record WHERE operation='API-191-PRIVATE-ACK' AND resource_id=?",Integer.class,shipment.id())).isZero();var first=claim("audit");var accepted=accepted();f.inventory.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->commands.finish(first,f.inventory.actor,shipment.id(),UUID.randomUUID(),accepted,null)).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{f.inventory.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}seconds=31;var replay=claim("audit");assertThat(replay.command()).isEqualTo(first.command());commands.finish(replay,f.inventory.actor,shipment.id(),UUID.randomUUID(),accepted,null);assertThat(claim("audit").completed()).isEqualTo(accepted);}
 @Test void twelveSourceClaimsPersistOneOutboundIdentity()throws Exception{var start=new CountDownLatch(1);int accepted=0;try(var pool=Executors.newFixedThreadPool(12)){var futures=new ArrayList<Future<Boolean>>();for(int i=0;i<12;i++)futures.add(pool.submit(()->{start.await();try{claim("race");return true;}catch(com.nigson.shared.problem.Problem.Failure busy){assertThat(busy.code.name()).isEqualTo("IDEMPOTENCY_IN_PROGRESS");return false;}}));start.countDown();for(var future:futures)if(future.get(15,TimeUnit.SECONDS))accepted++;}assertThat(accepted).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.idempotency_record WHERE operation='API-191-PRIVATE-ACK' AND resource_id=?",Integer.class,shipment.id())).isEqualTo(1);}
}
